<?php $companyId=$request->query['company']??($companies?reset($companies)['id']:null);$analytics=$companyId?$app->api('companies/'.$companyId.'/analytics'):['jobs'=>[],'applications'=>[],'scores'=>[]];$counts=array_column($analytics['applications'],'total','status');$jobCounts=array_column($analytics['jobs'],'total','status');$total=array_sum($counts);$average=(float)($analytics['scores']['averageScore']??0);$stages=['APPLIED'=>'Đã ứng tuyển','AI_SCREENING'=>'AI đánh giá','HR_REVIEW'=>'HR xem xét','INTERVIEW'=>'Phỏng vấn','OFFER'=>'Đề nghị','HIRED'=>'Đã tuyển','REJECTED'=>'Từ chối']; ?>
<section class="panel section"><form><label>Công ty<select name="company" onchange="this.form.requestSubmit()"><?php foreach($companies as $c): ?><option value="<?= e($c['id']) ?>" <?= $companyId===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label></form></section>
<div class="stat-cards recruiter-stats section"><?php foreach(['Tin tuyển dụng'=>array_sum($jobCounts),'Đang tuyển'=>$jobCounts['ACTIVE']??0,'Ứng viên'=>$total,'Điểm AI trung bình'=>round($average,1)] as $label=>$value): ?><section class="panel"><span class="muted"><?= e($label) ?></span><strong><?= e($value) ?></strong></section><?php endforeach; ?></div>
<div class="grid two section"><section class="panel"><h2>Ứng viên theo giai đoạn</h2><div class="analytics-bars section"><?php $max=max(1,...array_values($counts));foreach($stages as $stage=>$label):$count=(int)($counts[$stage]??0); ?><div><div class="row"><span><?= e($label) ?></span><strong><?= $count ?></strong></div><div class="chart-track"><span style="width:<?= round($count/$max*100,2) ?>%"></span></div></div><?php endforeach; ?></div></section><section class="panel"><h2>Chuyển đổi tuyển dụng</h2><?php $rate=$total?round(($counts['HIRED']??0)/$total*100,1):0; ?><div class="analytics-donut" style="--chart-progress:<?= $rate ?>%" role="img" aria-label="Tỷ lệ tuyển dụng <?= $rate ?> phần trăm"><div><strong><?= $rate ?>%</strong><span>Tỷ lệ tuyển dụng</span></div></div><div class="grid two"><div><strong><?= (int)($counts['HIRED']??0) ?></strong><p class="muted">Đã tuyển</p></div><div><strong><?= $total ?></strong><p class="muted">Tổng ứng viên</p></div></div></section></div>
<div class="grid two section"><section class="panel"><h2>Pipeline tuyển dụng</h2><div class="pipeline-funnel section"><?php foreach(['APPLIED','HR_REVIEW','INTERVIEW','OFFER','HIRED'] as $index=>$stage): ?><div style="width:<?= 100-$index*12 ?>%"><span><?= e($stages[$stage]) ?></span><strong><?= (int)($counts[$stage]??0) ?></strong></div><?php endforeach; ?></div></section><section class="panel"><h2>Chất lượng ứng viên</h2><div class="analytics-donut" style="--chart-progress:<?= max(0,min(100,$average)) ?>%"><div><strong><?= round($average,1) ?></strong><span>Điểm AI /100</span></div></div><p class="muted">Điểm trung bình của các hồ sơ đã được đánh giá AI.</p></section></div>